#!/bin/bash
# install-lab-docs.sh — recreate the full lab documentation set + tooling.
#   docs/    : 9 guides + 3 SVG diagrams
#   scripts/ : run-facts-export-prod.sh, harden-lab.sh, gather_licenses.py
# Run from the project root:  bash install-lab-docs.sh
set -euo pipefail
cd "$(dirname "$0")"

if [ ! -f ansible.cfg ] && [ ! -d playbooks ]; then
  echo "WARNING: does not look like the project root (no ansible.cfg/playbooks)."
  read -rp "Continue anyway? [y/N] " a; [ "$a" = "y" ] || exit 1
fi

mkdir -p docs scripts

echo "  writing docs/Lab-Guide-Rocky9-AccessControl.html"
base64 -d > 'docs/Lab-Guide-Rocky9-AccessControl.html' <<'B64EOF'
